syntax:
For a container 'c', an iterator is obtained via c.begin() and c.end(), and traversal is performed using a loop:

for (auto it = c.begin(); it != c.end(); ++it) {
    // Access element via *it
}

code_example:
#include <iostream>
#include <set>
int main() {
    std::set<int> numbers = {1, 2, 3, 4, 5, 6};
    for (auto it = numbers.begin(); it != numbers.end(); ++it) {
        std::cout << *it << ' ';
    }
    std::cout << std::endl;
    return 0;
}
